try {
    let {
        url = "",
        query = ""
    } = options;

    if (!(url instanceof URL)) {
        url = new URL(url);
    }

    const searchParams = new URLSearchParams(query);

    searchParams.forEach((value, key) => {
        if (key.endsWith('_in') || key.endsWith('_notin')) {
            let currentUrlString = url.toString();
            currentUrlString += currentUrlString.includes('?') ? '&' : '?';
            currentUrlString += `${encodeURIComponent(key)}=${encodeURIComponent(value)}`;
            url = new URL(currentUrlString);
        } else {
            url.searchParams.append(key, value);
        }
    });

    // Convert form-encoded spaces (+) to URI-encoded spaces (%20)
    // Actual + signs in the text are safely encoded as %2B, so this won't break them.
    url.search = url.search.replace(/\+/g, '%20');

    return url;

} catch (e) {
    console.error("Error building URL with query: ", e);
    return options.url;
}

const {
    entity,
    page = 1,
    limit = 25,
    query = "",
    customEntityKey = null,
    silent = false
} = options;

let {
    offset
} = options;

if (!entity) throw new Error("Entity is required for Payroll API calls.");

let url = new URL(`${this.config.baseUrl}/${entity}`);
const params = url.searchParams;

offset = offset ?? (page - 1) * limit;
params.set('limit', limit);
params.set('offset', offset);

if (query) {
    url = this._buildUrlWithQuery({ url, query }); 
}

try {
    const res = await this.httpService.request(url.toString(), 'GET');

    if (!res) return [];

    const entityKey = customEntityKey ?? entity.split("/")[0];
    const entities = res?.[entityKey] ?? res ?? [];

    if (Array.isArray(entities)) {
        return {
            entities,
            metadata: {
                totalFiltered: res?.metadata?.totalFiltered,
                totalCount: res?.metadata?.totalCount,
                pageCount: res?.metadata?.pageCount,
                currentPage: res?.metadata?.currentPage,
                hasNextPage: res?.metadata?.hasNextPage
            }
        };
    }

    return res;

} catch (error) {
    const msg = error.message || "An unexpected error occurred.";

    if (!silent) {
        this.utils.toast(msg, "ERROR");
    }
    throw error;
}

if (!path) throw new Error("Path is required for Payroll API POST calls.");

const url = `${this.config.baseUrl}/${path}`;

try {
    const res = await this.httpService.request(url, method, payload);
    return res;

} catch (error) {
    const msg = error.message || "An unexpected error occurred during save.";

    if (!silent) {
        this.utils.toast(msg, "ERROR");
    }
    throw error;
}
